725	\begin{lemma}[Formalization support for Lemma~\ref{lem:ld-sandwich}]
726		\label{lem:sandwich-root-distance-triangle}
727		\lean{MIPStarRE.QPBT.SandwichProduct.sqrt_opFamilyDistSq_triangle}
728		\leanok
729		\uses{def:povm-distance}
730		This formalization-only auxiliary isolates the triangle inequality used for
731		the repeated replacements in \cite[Fact~4.34]{Natarajan2018NEEXP}. For three operator
732		families $A,B,C$,
733		\[
734			\sqrt{D_\psi(A,C)}
735			\leq\sqrt{D_\psi(A,B)}+\sqrt{D_\psi(B,C)},
736		\]
737		where $D_\psi$ is the explicit averaged squared distance underlying
738		Definition~\ref{def:povm-distance}.
739	\end{lemma}
740	\begin{proof}
741		\leanok
742		\uses{lem:distance-nonnegative}
743		For each outcome write $(A-C)\ket\psi=(A-B)\ket\psi+(B-C)\ket\psi$,
744		apply Cauchy--Schwarz to the averaged cross term, and take square roots.
745	\end{proof}
